-- public.perform_relic_use(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.perform_relic_use(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_it item; v_stone item; v_recipe text; v_ferment record; v_rc recipe; v_serve record; v_other record;
        v_shares int; v_me player; v_seed text; v_e text; v_skill text := p_target->>'skill'; v_was double precision;
        v_now double precision;
begin
  if relic_use_refusal(p_world, p_uid, p_action, p_target) is not null then return; end if;
  v_it := carried(p_world, p_uid, target_item(p_target));

  if p_action = 'hone_whetstone' then
    -- All the damage off, the QL as it was; the whetstone used up.
    if not consume(p_world, p_uid, 'ancient_whetstone', 1) then return; end if;
    update item set dmg = 0 where id = v_it.id returning * into v_it;
    perform tell(p_world, p_uid, 'Honed: ' || lower(item_name(v_it)) || ', all damage off, QL '
      || round(v_it.ql::numeric, 1) || '. Whetstone used up.', 'event');

  elsif p_action = 'open_ferment' then
    -- What it was set going to make, at its QL and rarity, and the vessel back (`FERMENT_ACTIONS`).
    select * into v_ferment from ferment_recipes() f where f.title = v_it.extra;
    select * into v_rc from recipe where id = v_ferment.id;
    if v_rc.id is null or not spend_stack(p_world, p_uid, v_it.id, 1) then return; end if;
    perform give(p_world, p_uid, v_rc.result, v_rc.count, v_it.ql, v_rc.extra, v_it.rare);
    perform give(p_world, p_uid, v_ferment.vessel, 1, vessel_back_ql());
    perform journal_made(p_world, p_uid, v_rc.result, v_it.ql, v_rc.count, v_it.rare);
    perform tell(p_world, p_uid, craft_made_said(v_rc.result, v_rc.count, null, v_it.ql, v_rc.done), 'event');

  elsif p_action = 'serve_dish' then
    -- One share to each other player awake and ashore in reach, nearest first, the rest to the server (`FEAST_ACTIONS`).
    select * into v_serve from serve_dishes() s where s.item = v_it.def;
    select * into v_me from player pl where pl.world_id = p_world and pl.uid = p_uid;
    if v_serve.item is null or not spend_stack(p_world, p_uid, v_it.id, 1) then return; end if;
    v_shares := 0;
    for v_other in
      select o.uid from player o
       where o.world_id = p_world and o.uid <> p_uid and not o.away
         and o.seen_at > now() - make_interval(secs => idle_logout())
         and sqrt((o.x - v_me.x) ^ 2 + (o.y - v_me.y) ^ 2) <= v_serve.reach
       order by sqrt((o.x - v_me.x) ^ 2 + (o.y - v_me.y) ^ 2)
       limit greatest(0, v_serve.count - 1)
    loop
      perform give(p_world, v_other.uid, v_serve.serving, 1, v_it.ql);
      perform tell(p_world, v_other.uid, 'Served to you: ' || lower((select d.name from item_def d where d.id = v_serve.serving))
        || ', by ' || v_me.name || '.', 'event');
      v_shares := v_shares + 1;
    end loop;
    perform give(p_world, p_uid, v_serve.serving, v_serve.count - v_shares, v_it.ql);
    perform tell(p_world, p_uid, 'Served: ' || lower((select d.name from item_def d where d.id = v_it.def))
      || '. Shares: ' || v_shares || ' to others, ' || (v_serve.count - v_shares) || ' to you.', 'event');

  elsif p_action in ('read_recipe', 'read_formula') then
    -- The recipe it opens, read for good; the Recipe or Formula used up (`recipebook.ts`).
    v_recipe := private.book_opens(v_it.def, v_it.extra);
    if v_recipe is null or not spend_stack(p_world, p_uid, v_it.id, 1) then return; end if;
    insert into private.recipe_known (world_id, uid, recipe) values (p_world, p_uid, v_recipe) on conflict do nothing;
    perform tell(p_world, p_uid, (select idf.name from item_def idf where idf.id = v_it.def) || ' read: '
      || (select l.title from locked_recipes() l where l.id = v_recipe)
      || '. ' || (select idf.name from item_def idf where idf.id = v_it.def) || ' used up.', 'skill');

  elsif p_action = 'open_seed_jar' then
    -- `jar_seeds` seeds of one crop at random, at the jar's QL.
    select c.seed into v_seed from crop_def c order by random() limit 1;
    if not spend_stack(p_world, p_uid, v_it.id, 1) then return; end if;
    perform give(p_world, p_uid, v_seed, jar_seeds()::int, v_it.ql);
    perform tell(p_world, p_uid, 'Seed jar opened: ' || jar_seeds()::int || ' × '
      || lower((select d.name from item_def d where d.id = v_seed)) || ', QL ' || round(v_it.ql::numeric, 1) || '.', 'event');

  elsif p_action = 'enchant_statue' then
    -- `statue_motes` of every element used up, and the statuette the patron's statue where it lies, as it was.
    foreach v_e in array mote_elements() loop
      perform consume(p_world, p_uid, v_e || '_mote', statue_motes());
    end loop;
    update item set def = patron_statue(p_target->>'patron') where id = v_it.id returning * into v_it;
    perform skill_raise(p_world, p_uid, enchanting_skill(), 1);
    perform tell(p_world, p_uid, 'Enchanted: ' || (select d.name from item_def d where d.id = v_it.def) || ', QL '
      || to_char(v_it.ql, 'FM990.0') || '. ' || statue_motes() * array_length(mote_elements(), 1) || ' motes used up.', 'event');

  else
    -- `tablet_gain` into the skill chosen, all at once; the tablet used up.
    if not spend_stack(p_world, p_uid, v_it.id, 1) then return; end if;
    v_was := skill_standing(p_world, p_uid, v_skill);
    v_now := v_was + tablet_gain();
    insert into skill (world_id, uid, id, value) values (p_world, p_uid, v_skill, v_now)
      on conflict (world_id, uid, id) do update set value = excluded.value;
    update player set skills_at = now() where world_id = p_world and uid = p_uid;
    perform earn_titles(p_world, p_uid, v_skill, v_was, v_now);
    perform tell(p_world, p_uid, 'Rune tablet read: ' || (select d.name from skill_def d where d.id = v_skill) || ' '
      || to_char(v_now, 'FM999990.0000') || ' (+' || to_char(tablet_gain(), 'FM990.0') || '). Tablet used up.', 'skill');
  end if;
end $function$
